rapla:artifact.body:
query ArrivalsThisWeek($filter: ReservationFilter!) @view(title: "Arrivals this week", rowLabel: "Stay|Stays", renderModes: [grouped])
  @window(from: {anchor: WEEK_START}, to: {anchor: WEEK_START, offset: 7})
{
  appointmentBlocks(filter: $filter) {
    day: compute(expr: "{p->format(\"%1$tA %1$td.%1$tm.\",start(p))}") @column(group: true) @hidden
    from: compute(expr: "{p->format(\"%1$ta %1$td.%1$tm. %1$tH:%1$tM\",start(p))}") @column(header: "Arrival", order: 1)
    to: compute(expr: "{p->format(\"%1$ta %1$td.%1$tm. %1$tH:%1$tM\",end(p))}") @column(header: "Departure", order: 2)
    name @column(header: "Seminar", order: 3)
    kind: compute(expr: "{kind}") @column(header: "Kind", order: 4)
    participants: compute(expr: "{participants}") @column(header: "Participants", order: 5)
    guestRooms: resources(filter: { typeIn: [guestrooms] }) @join(separator: ", ") @column(header: "Guest rooms", order: 6) { name }
    trainer: resources(filter: { typeIn: [trainer] }) @join(separator: ", ") @column(header: "Trainer", order: 7) { name }
    color @hidden
    reservation @hidden { id canModify classification { typeKey } }
  }
}

query Programme($filter: ReservationFilter!) @view(title: "Programme", rowLabel: "Seminar|Seminars", renderModes: [grouped, table])
  @window(from: {anchor: MONTH_START}, to: {anchor: MONTH_START, offset: 6, unit: MONTHS})
{
  appointmentBlocks(filter: $filter) {
    month: compute(expr: "{p->format(\"%1$tB %1$tY\",start(p))}") @column(group: true) @hidden
    from: compute(expr: "{p->format(\"%1$ta %1$td.%1$tm. %1$tH:%1$tM\",start(p))}") @column(header: "From", order: 1)
    to: compute(expr: "{p->format(\"%1$ta %1$td.%1$tm. %1$tH:%1$tM\",end(p))}") @column(header: "To", order: 2)
    name @column(header: "Seminar", order: 3)
    kind: compute(expr: "{kind}") @column(header: "Kind", order: 4)
    participants: compute(expr: "{participants}") @column(header: "Participants", order: 5)
    trainer: resources(filter: { typeIn: [trainer] }) @join(separator: ", ") @column(header: "Trainer", order: 6) { name }
    color @hidden
    reservation @hidden { id canModify classification { typeKey } }
  }
}
